#!/usr/bin/env node
/**
 * Computes the vertex and edge counts, components (H0), cycle rank (H1), and Euler characteristic of one relation attribute's bipartite graph over eavt rows.
 * @param {object} request A record with rows and the relation attribute.
 * @returns {object} An EavtRelationNerve record.
 * @throws {TypeError} When rows is not an array or attribute is not a non-empty string.
 */
export function countEavtRelationNerve(request) {
  if (!Array.isArray(request?.rows) || typeof request?.attribute !== "string" || request.attribute.length === 0) {
    throw new TypeError("rows and a non-empty attribute are required");
  }
  const parent = new Map();
  const find = (key) => {
    if (!parent.has(key)) parent.set(key, key);
    let root = key;
    while (parent.get(root) !== root) root = parent.get(root);
    let current = key;
    while (parent.get(current) !== root) { const next = parent.get(current); parent.set(current, root); current = next; }
    return root;
  };
  const edges = new Set();
  for (const row of request.rows) {
    if (row.a !== request.attribute) continue;
    const subject = `s:${String(row.e)}`;
    const object = `o:${typeof row.v === "string" ? row.v : JSON.stringify(row.v)}`;
    const edge = `${subject}�${object}`;
    if (edges.has(edge)) continue;
    edges.add(edge);
    const a = find(subject);
    const b = find(object);
    if (a !== b) parent.set(a, b);
  }
  const vertices = parent.size;
  const edgeCount = edges.size;
  let components = 0;
  for (const key of parent.keys()) if (find(key) === key) components += 1;
  const cycles = edgeCount - vertices + components;
  return { type: "EavtRelationNerve", attribute: request.attribute, vertices, edges: edgeCount, h0: components, h1: cycles, chi: vertices - edgeCount };
}

if (import.meta.main) {
  if (process.argv.includes("--help")) {
    process.stdout.write("countEavtRelationNerve — Computes the vertex and edge counts, components (H0), cycle rank (H1), and Euler characteristic of one relation attribute's bipartite graph over eavt rows.\n");
  } else {
    let text = "";
    for await (const chunk of process.stdin) text += chunk;
    for (const line of text.split("\n")) {
      if (line.length > 0) process.stdout.write(`${JSON.stringify(countEavtRelationNerve(JSON.parse(line)))}\n`);
    }
  }
}

